-- LISO + PELE BRANCA (25 combinações)
INSERT INTO recomendacoes (criterio, descricao, ativo, created_at, updated_at) VALUES
('LISO_BRANCA_OVAL_CLASSICO', 'Para cabelos lisos com pele branca e rosto oval, recomendamos um corte clássico em camadas médias com franja lateral. O estilo clássico valoriza a simetria do rosto oval. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_OVAL_MODERNO', 'Para cabelos lisos com pele branca e rosto oval, sugerimos um corte moderno com assimetria e textura. O estilo moderno adiciona personalidade ao visual. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_OVAL_ROMANTICO', 'Para cabelos lisos com pele branca e rosto oval, recomendamos um corte em camadas longas com volume lateral. O estilo romântico cria um visual delicado. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_OVAL_AVENTUREIRO', 'Para cabelos lisos com pele branca e rosto oval, sugerimos um corte pixie moderno ou bob assimétrico. O estilo aventureiro traz ousadia ao visual. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_OVAL_MINIMALISTA', 'Para cabelos lisos com pele branca e rosto oval, recomendamos um corte bob médio limpo e simétrico. O estilo minimalista mantém a simplicidade e elegância. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_REDONDO_CLASSICO', 'Para cabelos lisos com pele branca e rosto redondo, recomendamos cortes em camadas longas ou repicadas, com volume no topo e laterais suavizadas. O estilo clássico alonga o rosto e valoriza a altura. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_REDONDO_MODERNO', 'Para cabelos lisos com pele branca e rosto redondo, sugerimos cortes modernos com franja lateral e camadas desconectadas. O estilo moderno traz leveza e movimento. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_REDONDO_ROMANTICO', 'Para cabelos lisos com pele branca e rosto redondo, indicamos cortes em camadas suaves com pontas desfiadas. O estilo romântico suaviza as linhas do rosto. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_REDONDO_AVENTUREIRO', 'Para cabelos lisos com pele branca e rosto redondo, sugerimos cortes curtos e assimétricos, como o pixie. O estilo aventureiro destaca a personalidade. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_REDONDO_MINIMALISTA', 'Para cabelos lisos com pele branca e rosto redondo, recomendamos cortes retos na altura do queixo, com pouco volume nas laterais. O estilo minimalista alonga o rosto. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_QUADRADO_CLASSICO', 'Para cabelos lisos com pele branca e rosto quadrado, sugerimos cortes com camadas suaves e franjas laterais. O estilo clássico suaviza as linhas do maxilar. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_QUADRADO_MODERNO', 'Para cabelos lisos com pele branca e rosto quadrado, indicamos cortes modernos com pontas desconectadas e assimetria. O estilo moderno traz harmonia ao visual. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_QUADRADO_ROMANTICO', 'Para cabelos lisos com pele branca e rosto quadrado, recomendamos cortes em camadas longas e franjas leves. O estilo romântico suaviza o contorno do rosto. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_QUADRADO_AVENTUREIRO', 'Para cabelos lisos com pele branca e rosto quadrado, sugerimos cortes curtos e despojados, como o bob assimétrico. O estilo aventureiro destaca o visual. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_QUADRADO_MINIMALISTA', 'Para cabelos lisos com pele branca e rosto quadrado, indicamos cortes retos e simétricos, na altura do queixo. O estilo minimalista valoriza a simplicidade. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_DIAMANTE_CLASSICO', 'Para cabelos lisos com pele branca e rosto diamante, sugerimos cortes que criam volume na testa e no queixo, equilibrando as proporções. O estilo clássico valoriza a beleza natural do formato. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_DIAMANTE_MODERNO', 'Para cabelos lisos com pele branca e rosto diamante, indicamos cortes modernos com franja longa e camadas desconectadas. O estilo moderno destaca o formato do rosto. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_DIAMANTE_ROMANTICO', 'Para cabelos lisos com pele branca e rosto diamante, recomendamos cortes em camadas suaves e volume lateral. O estilo romântico equilibra as proporções. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_DIAMANTE_AVENTUREIRO', 'Para cabelos lisos com pele branca e rosto diamante, sugerimos cortes curtos e despojados, como o pixie. O estilo aventureiro traz ousadia ao visual. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_DIAMANTE_MINIMALISTA', 'Para cabelos lisos com pele branca e rosto diamante, indicamos cortes retos e simétricos, com pouco volume. O estilo minimalista valoriza a simplicidade. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_TRIANGULAR_CLASSICO', 'Para cabelos lisos com pele branca e rosto triangular, sugerimos cortes que adicionam volume na parte superior e franjas. O estilo clássico equilibra o visual. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_TRIANGULAR_MODERNO', 'Para cabelos lisos com pele branca e rosto triangular, indicamos cortes modernos com camadas desconectadas e franja lateral. O estilo moderno traz leveza ao visual. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_TRIANGULAR_ROMANTICO', 'Para cabelos lisos com pele branca e rosto triangular, recomendamos cortes em camadas longas e volume no topo. O estilo romântico suaviza o formato. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
('LISO_BRANCA_TRIANGULAR_AVENTUREIRO', 'Para cabelos lisos com pele branca e rosto triangular, sugerimos cortes curtos e assimétricos, como o bob. O estilo aventureiro destaca a personalidade. Tons de cor recomendados: castanho claro, loiro dourado ou caramelo suave.', true, NOW(), NOW()),
